mapper.select:
SELECT o.*, u.username as user_name, m.username as merchant_name FROM `order` o LEFT JOIN user u ON o.user_id = u.id LEFT JOIN user m ON o.merchant_id = m.id
AND o.status = #{status}
ORDER BY o.create_time DESC

mapper.update:
UPDATE `order`
status = #{status}, address = #{address}, receiver_name = #{receiverName}, receiver_phone = #{receiverPhone}, pay_time = #{payTime}, ship_time = #{shipTime}, receive_time = #{receiveTime}, update_time = #{updateTime}
WHERE id = #{id}

mapper.select:
SELECT COALESCE(SUM(total_amount), 0) FROM `order`


        AND merchant_id = #{merchantId}

    AND status IN (1, 2, 3)
